<template>
    <div class="container">
        <div class="row">
            <h2>{{this.$router.currentRoute.value.name}}</h2>
            <div class="col-xs-12 col-sm-12">   
                <div class="block block-data">
                    <div class="inner">
                        <table class="table" style="border-collapse:collapse;">
                            <thead>
                                <th>
                                    Username
                                </th>
                                <th>
                                    Email
                                </th>
                                <th>
                                    IsAdmin
                                </th>
                                <th>
                                    Status
                                </th>
                            </thead>
                            <tbody>
                                <tr v-for="row in data" :key="row.username">
                                    <td>
                                        {{row.username}}
                                    </td>
                                    <td>
                                        {{row.recoveryEmail}}
                                    </td>
                                    <td>
                                        {{row.isAdmin}}
                                    </td>
                                    <td>
                                        {{new Date(new Date((row.sessionExpireDateTime ?? "1970-01-01T00:00:00.000Z").slice(0, 19) + ".000Z")) > new Date(new Date().toISOString()) ? 'Online' : 'Offline'}}
                                    </td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                    <br>
                    <label for="Username">Write username of account you want to delete</label>
                    <br />
                    <input id="Username" autocomplete="new-password" class="form-control" maxlength="100" style="display:inline-block; width:90%" v-on:keyup.enter="deleteUser($event)" v-model="username"/>
                    <span class="tdspaced" style="color: red;" v-if="triedDeleting && !username.trim()">*</span>
                    <br />
                    <button id="DeleteUser" class="btn btn-danger profileBtn" @click="deleteUser($event)">Delete User and Data</button>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";

export default {
  name: "AdminIstration",
  data() {
    return {
        data: [],
        username: "",
        triedDeleting: false
    }
  },
  
  async mounted() {
    this.$store.state.loading = true;

    this.data = await this.getData();

    this.$store.state.loading = false;
  },
  methods: {
    focus(id) {
        document.getElementById(id).focus();
    },
    async getData() {
        this.$store.state.loading = true;
        
        let result = await CommunicationHelpers.apiDataCall("/api/v1/admin/GetAllUsers", this.$store.state, 'GET', null, false);

        this.$store.state.loading = false;

        return result;
    },
    async deleteUser(event) {
        this.triedDeleting = true;

        if(!this.username.trim()) {
            event.preventDefault();
        } else {
            if(confirm("Are you sure you want to delete user and all data?")) {
                this.$store.state.loading = true;

                this.triedDeleting = false;

                this.$store.state.searchString = this.username;
                
                if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/admin/DeleteUser", this.$store.state, 'DELETE',
                    { 'username': this.$store.state.searchString }, false))) {
                    this.username = "";
                }

                this.data = await this.getData();

                this.$store.state.loading = false;
            }
        }
    }
  }
};
</script>