<template>
  <div class="container">
    <div class="row">
      <h2>Categories</h2>
      <div class="col-xs-12 col-sm-4 col-md-3 name_pos_1">
        <div class="block-data block" style="min-height: 0px!important">
          <h3>Tips</h3>
          <hr>
          <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
            Here you can define your income or expense <b><i>categories</i></b> that will be used for each data entry in <b><i>finance</i></b> tab. It is more efficient to manage your <b><i>finance</i></b> if you group them using <b><i>categories</i></b>!
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-8 col-md-9">
        <div class="block block-data inner">
          <div class="inner">
            <div class="searchbar">
              <button id="NewButton" @click="insert()" data-toggle="modal" data-target="#detailModal" class="btn btn-primary up"><b>+</b> Add Category</button>
              <input id="Search" class="form-control search-box" maxlength="100" placeholder="Search" v-model="$store.state.searchString" @keyup="keyup" />
              <multiselect class="pageSize" id="PageFilter" v-model="pageSize" :searchable="false" :show-labels="false"
                :closeOnSelect="true" :options="['10','15','20','25']" :preselectFirst="true" :allowEmpty="false"
                placeholder="Select" openDirection="bottom" >
              </multiselect>
            </div>
            <div class="table-place">
              <table class="table names">
                <thead>
                    <th class="names-nr">
                        Nr.
                    </th>
                    <th class="names-name">
                        Name
                    </th>
                    <th class="names-parent">
                        Parent
                    </th>
                </thead>
                <tbody>
                  <tr v-if="$store.state.dataset.items.length == 0">
                    <td colspan="5" class="no-data">No data available in table</td>
                  </tr>
                  <tr v-else v-for="(row, i) in $store.state.dataset.items" :key="row.id" @click="edit(row, i)" data-toggle="modal" data-target="#detailModal" :class="selected == row.id ? 'selected' : ''">
                    <td class="names-nr">
                      {{i + 1 + $store.state.from}}
                    </td>
                    <td class="names-name">
                      <div class="overflow-ellipsis">{{row.name}}</div>
                    </td>
                    <td class="names-parent">
                      <div class="overflow-ellipsis">{{getParentName(row.parentId) ?? "-"}}</div>
                    </td>

                  </tr>
                </tbody>
              </table>
            </div>
            <Pagination :visibleButtonNumber="5" :baseUrl="'/api/v1/categories/List'" :mvvMGetter="getMvvMCategory()" />
          </div>
        </div>
      </div>
      <div class="col-xs-12 col-sm-4 col-md-3 name_pos_2">
        <div class="block" style="min-height: 0px!important">
          <h3>Tips</h3>
          <hr>
          <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
            Here you can define your income or expense <b><i>names</i></b> that will be used for each data entry in <b><i>finance</i></b> tab. It is more efficient to manage your <b><i>finance</i></b> if you group them using <b><i>names</i></b>!
          </div>
        </div>
      </div>
    </div>
  </div>

  <div id="detailModal" class="modal fade" role="dialog" :v-model="this.selected">
    <div class="vertical-alignment-helper">
      <div class="modal-dialog vertical-align-center">
        <div class="modal-content">
          <div class="modal-header">
            <button type="button" class="close" data-dismiss="modal">&times;</button>
            <h4 class="modal-title">
            </h4>
          </div>
          <div class="modal-body">
            <div v-if="!this.selectedName || this.selectedName.categories.length == 0">
              <label for="Parent">Parent</label>
              <br />
              <multiselect class="form-text-valid" id="Parent" v-model="selectedParent" :show-labels="false"
                :closeOnSelect="true" :options="this.parents.filter(parent => parent.id != this.selected)"
                placeholder="-" track-by="id" label="name" openDirection="bottom" >
                <template #noResult>
                  <span>No categories found.</span>
                </template>
              </multiselect>
              <br />
              <br />
            </div>
            <label for="Name">Name</label>
            <br />
            <input id="Name" class="form-control form-text-valid" maxlength="100" @change="change($event)" v-on:keyup.enter="focus()" v-model="name" />
            <span class="tdspaced" style="color: red;" v-if="triedSubmitting && !name.trim()">*</span>
            <div v-if="this.selectedName && this.selectedName.categories.length == 0">
              <br />
              <button id="DeleteReferencesButton" @click="deleteReferences($event)" class="btn btn-danger">Delete all references to '{{this.selectedName.name}}' category</button>
            </div>
            <div v-if="this.selectedName && this.selectedName.categories.length > 0">
              <br />
              <label for="Children">Children</label>
              <br />
              <table id="Children" class="table children">
                <thead>
                    <th class="children-nr">
                        Nr.
                    </th>
                    <th class="children-name">
                        Name
                    </th>
                </thead>
                <tbody>
                  <tr v-for="(row, i) in this.selectedName?.categories" :key="row.id">
                    <td class="children-nr">
                      {{i + 1}}
                    </td>
                    <td class="children-name">
                      {{row.name}}
                    </td>
                  </tr>
                </tbody>
              </table>
              
            </div>
          </div>
          <div class="modal-footer">
            <div id="newControl">
              <button id="AddButton" @click="addRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <div id="editControl">
              <button v-if="!this.selectedName || this.selectedName.categories.length == 0" id="DeleteButton" @click="deleteRecord($event)" class="btn btn-danger leftside">Delete</button>
              <button v-else id="AggregateChildrenButton" @click="aggregateChildren($event)" class="btn btn-danger leftside">Aggregate all children to '{{this.selectedName.name}}'</button>
              <button id="SaveButton" @click="saveRecord($event)" class="btn btn-primary rightside">Save</button>
            </div>
            <button id="close" type="button" class="btn btn-default rightside" data-dismiss="modal" style="display:inline-block">Close</button>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import jQuery from "jquery";
import Pagination from '../../Pagination/Pagination.vue';
import CommunicationHelpers from '../../../helpers/CommunicationHelpers.js';
import { GetMvvMCategory } from '../../../models/MvvMCategory.js';
import Dataset from '@/models/Dataset';
import Multiselect from 'vue-multiselect';
const $ = jQuery;
window.$ = $;

export default {
  name: "NaMes",
  components: {
    Pagination,
    Multiselect
  },
  data() {
    return {
      pageSize: 10,
      selected: null,
      selectedParent: null,
      selectedName: null,
      parents: [],
      name: "",
      oldName: "",
      triedSubmitting: false
    }
  },
  beforeMount() {
    this.$store.state.dataset = new Dataset();
  },
  async mounted() {
    this.$store.state.loading = true;

    await this.setup();

    this.$store.state.loading = false;
  },
  methods: {
    focus() {
      if(this.selected) {
        document.getElementById("SaveButton").click();
      } else {
        document.getElementById("AddButton").click();
      }
    },
    async setup() {
      this.parents = await CommunicationHelpers.apiDataCall("/api/v1/categories/ListParents", this.$store.state, 'GET', null, false);
      this.selectedParent = null;

      this.$store.state.dataset.setPerPage(this.pageSize);
      await this.search();
    },
    async search() {
      this.$store.state.dataset.currentPage = 1;
      this.selected = null;
      this.selectedName = null;

      await this.getData();
    },
    async keyup() {
      // if (this.$store.state.loading) {
      //   event.preventDefault();
      // } else {
        await this.search();
      // }
    },
    insert() {
      this.selected = "";
      this.selectedName = null;
      this.oldName = "";
      this.name = "";

      document.getElementsByClassName("modal-title")[0].innerHTML = "Add new record";
      document.getElementById("newControl").style.display = "block";
      document.getElementById("editControl").style.display = "none";
    },
    edit(row, i) {
      this.selected = row.id;
      this.selectedName = this.getSelectedName();

      let parent = this.getParent() ?? null;

      this.selectedParent = parent;
      this.name = row.name.trim();

      this.oldParent = parent;
      this.oldName = row.name.trim();

      document.getElementsByClassName("modal-title")[0].innerHTML = "Edit record nr. <b>" + (i + 1 + this.$store.state.from) + "</b>";
      document.getElementById("newControl").style.display = "none";
      document.getElementById("editControl").style.display = "block";
    },
    getParentName(parentId) {
      let toReturn = null;

      if (parentId != null){
        let parent = this.parents.find(name => name.id == parentId);

        if (parent != null) {
          toReturn = parent.name;
        }
      }

      return toReturn;
    },
    getParent() {
      let toReturn = null;

      if (this.selectedName != null) {
        toReturn = this.parents.find(name => name.id == this.selectedName.parentId);
      }

      return toReturn;
    },
    getSelectedName() {
      return this.$store.state.dataset.items.find(name => name.id == this.selected);
    },
    async addRecord(event) {
      this.triedSubmitting = true;

      if(!this.name.trim()) {
        event.preventDefault();
      } else {
        this.$store.state.loading = true;

        this.triedSubmitting = false;

        this.$store.state.categories.id = 0;
        this.$store.state.categories.name = this.name.trim();
        this.$store.state.categories.parentId = this.selectedParent?.id;

        if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/categories", this.$store.state, 'POST',
          { 'id': this.$store.state.categories.id, 'name': this.$store.state.categories.name, 'parentId': this.$store.state.categories.parentId ?? '' }, true))) {
          this.name = "";
          this.selectedParent = null;
          document.getElementById("close").click();

          this.parents = await CommunicationHelpers.apiDataCall("/api/v1/categories/ListParents", this.$store.state, 'GET', null, false);

          await this.search();
        }

        this.$store.state.loading = false;
      }
    },
    async saveRecord(event) {
      this.triedSubmitting = true;

      if(!this.name.trim()) {
          event.preventDefault();
      } else {
        this.triedSubmitting = false;

        if((this.selectedParent != this.oldParent ||
            this.name.trim() != this.oldName) && this.selected) {
          this.$store.state.loading = true;

          this.$store.state.categories.id = this.selected;

          this.$store.state.categories.name = this.name.trim();
          this.$store.state.categories.parentId = this.selectedParent?.id;

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/categories", this.$store.state, 'PUT',
          { 'id': this.$store.state.categories.id, 'name': this.$store.state.categories.name, 'parentId': this.$store.state.categories.parentId ?? '' }, true))) {
            this.name = "";
            this.selectedParent = null;
            document.getElementById("close").click();

            this.parents = await CommunicationHelpers.apiDataCall("/api/v1/categories/ListParents", this.$store.state, 'GET', null, false);

            await this.search();
          }

          this.$store.state.loading = false;
        } else {
          document.getElementById("close").click();
        }
      }
    },
    async deleteRecord(event) {
      if(!this.selected) {
        event.preventDefault();
      } else {
        if(confirm("Are you sure you want to delete?")) {
          this.$store.state.loading = true;

          this.$store.state.categories.id = this.selected;

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/categories/" + this.$store.state.categories.id, this.$store.state, 'DELETE', null, false))) {
            this.name = "";
            this.selectedParent = null;
            document.getElementById("close").click();
            this.$store.state.dataset.items = [];

            this.parents = await CommunicationHelpers.apiDataCall("/api/v1/categories/ListParents", this.$store.state, 'GET', null, false);

            await this.search();
          }

          this.$store.state.loading = false;
        }
      }
    },
    async deleteReferences(event) {
      if(!this.selected) {
        event.preventDefault();
      } else {
        if(confirm("Are you sure you want to delete all references to '" + this.selectedName.name + "' category?")) {
          this.$store.state.loading = true;

          this.$store.state.categories.id = this.selected;

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/categories/DeleteReferences/" + this.$store.state.categories.id, this.$store.state, 'DELETE', null, false))) {
            this.name = "";
            this.selectedParent = null;
            document.getElementById("close").click();
            this.$store.state.dataset.items = [];

            this.parents = await CommunicationHelpers.apiDataCall("/api/v1/categories/ListParents", this.$store.state, 'GET', null, false);

            await this.search();
          }

          this.$store.state.loading = false;
        }
      }
    },
    async aggregateChildren(event) {
      if(!this.selected) {
        event.preventDefault();
      } else {
        if(confirm("Are you sure you want to aggregate all children to '" + this.selectedName.name + "' category?")) {
          this.$store.state.loading = true;

          this.$store.state.categories.id = this.selected;

          if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/categories/AggregateChildren/" + this.$store.state.categories.id, this.$store.state, 'PUT', null, false))) {
            this.name = "";
            this.selectedParent = null;
            document.getElementById("close").click();
            this.$store.state.dataset.items = [];

            this.parents = await CommunicationHelpers.apiDataCall("/api/v1/categories/ListParents", this.$store.state, 'GET', null, false);

            await this.search();
          }

          this.$store.state.loading = false;
        }
      }
    },
    getMvvMCategory() {
      return GetMvvMCategory;
    },
    async getData() {
      this.$store.state.loading = true;

      await this.$store.state.dataset.setPage(this.$store, '/api/v1/categories/List', GetMvvMCategory);

      this.$store.state.loading = false;
    },
    async change() {
      this.$store.state.categories.name = this.name.trim();
      this.$store.state.categories.parentId = this.selectedParent?.id;

      let result = await CommunicationHelpers.apiDataCall("/api/v1/categories/IsDuplicate", this.$store.state, 'GET', { 'categoryName': this.$store.state.categories.name, parentId: this.$store.state.categories.parentId ?? '' }, false);

      if(result == "true" && this.name.trim() != this.oldName) {
        alert("Name like that already exists. Choose different");
        this.name = this.oldName;
        this.selectedParent = this.oldParent;
      }
    }
  },
  watch: {
    pageSize: async function() {
      this.$store.state.dataset.setPerPage(this.pageSize);

      await this.search();
    }
  },
  beforeRouteLeave(to, from, next) {
    this.$store.state.from = 0;
    this.$store.state.take = 0;
    this.$store.state.searchString = "";
    next();
  }
};
</script>
<style src="vue-multiselect/dist/vue-multiselect.min.css"></style>