<template>
    <div class="container" id="login">
        <div class="row">
            <div class="col-xs-12 col-sm-6 col-md-7 col-lg-8 hiden">
                <AboutInfo />
            </div>
            <div class="col-xs-12 col-sm-6 col-md-5 col-lg-4" id="HowToBlock" v-if="$store.state.tokenModel">
                <div class="block block-login short-bottom">
                    <h3>Main controls</h3>
                    <hr>
                    <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
                        <ul>
                            <li><i><b>Finance</b></i> - manage your finance records</li>
                            <br />
                            <li><i><b>Periodic Transactions</b></i> - automate your transactions</li>
                            <br />
                            <li><i><b>Accounts</b></i> - manage your accounts</li>
                            <br />
                            <li><i><b>Categories</b></i> - manage your finance record <i>categories</i></li>
                            <br />
                            <li><i><b>Overview</b></i> - check your finance report</li>
                            <br />
                            <li><i><b>Contact Us</b></i> - contact the owner of web page</li>
                            <br />
                            <li><i><b>Profile</b></i> - change your password, import and export data</li>
                            <br />
                            <li><i><b>Logout</b></i> - end this session</li>
                        </ul>
                    </div>
                </div>
                <div v-if="$store.state.shortHomePageUpdate" class="block showinmobile" style="min-height:0px!important; text-align: center;">
                    <div v-html="$store.state.shortHomePageUpdate"></div>
                </div>
                <div class="block" style="min-height:0px!important; text-align: center; padding:0px!important;">
                    <a style="width:100%; padding:14px;" class="btn" :href="$store.state.apkDownloadUrl" target="_blank">
                        {{$store.state.isWeb ? "Download Android App" : "Download latest version"}}
                    </a>                                      
                </div>
                <div class="block" style="min-height:0px!important; text-align: center; padding:0px!important;">
                    <a style="width:100%; padding:14px;" class="btn showinmobile" @click="openPage('About')">About</a>
                    <a style="width:100%; padding:14px;" class="btn" @click="openPage('ContactUs')">Contact Us</a>
                </div>
            </div>
            <div class="col-xs-12 col-sm-6 col-md-5 col-lg-4" id="LoginBlock" v-if="!$store.state.tokenModel">
                <div class="block block-login" style="min-height:0px!important">
                    <div>
                        <h3>Log In</h3>
                        <table>
                            <tr>
                                <td class="tdspaced"><label for="Username" id="UserNameLabel">Login:</label></td>
                                <td class="tdspaced"><input id="Username" class="form-control" maxlength="100" v-on:keyup.enter="focus('Password')" v-model="username" /></td>
                                <td class="tdspaced" style="color: red;" v-if="triedLogging && !username.trim()">*</td>
                            </tr>
                            <tr>
                                <td class="tdspaced"><label for="Password"  id="PasswordLabel">Password:</label></td>
                                <td class="tdspaced"><input type="password" id="Password" class="form-control" maxlength="100" v-on:keyup.enter="login($event)" v-model="password" /></td>
                                <td class="tdspaced" style="color: red;" v-if="triedLogging && !password.trim()">*</td>

                                <td class="tdspaced" v-if="!(triedLogging && !password.trim())">&nbsp;</td>
                            </tr>
                        </table>

                        <div class="checkbox" v-if="$store.state.isWeb">
                            <input type="checkbox" id="RememberMe" checked/>
                            <label for="RememberMe">Remember me next time</label>
                        </div>
                        <button id="LoginButton" class="btn btn-primary" style="width: 60%" @click="login($event)">Log in</button>
                        <br />
                        <span id="failureText" style="color: red; text-align:center; width:100%; display:block" v-if="triedLogging && !$store.state.tokenModel">Please try again</span>
                    </div>
                </div>
                <div v-if="$store.state.shortHomePageUpdate" class="block showinmobile" style="min-height:0px!important; text-align: center;">
                    <div v-html="$store.state.shortHomePageUpdate"></div>
                </div>
                <div class="block" style="min-height:0px!important; text-align: center; padding:0px!important;">
                    <a style="width:100%; padding:14px;" class="btn" @click="openPage('Register')">Sign Up</a>
                    <a style="width:100%; padding:14px;" class="btn" @click="openPage('Recover')">Recover Password</a>
                    <a style="width:100%; padding:14px;" class="btn showinmobile" @click="openPage('About')">About</a>
                    <a style="width:100%; padding:14px;" class="btn" @click="openPage('ContactUs')">Contact Us</a>
                    <a style="width:100%; padding:14px;" class="btn" :href="$store.state.apkDownloadUrl" target="_blank">
                        {{$store.state.isWeb ? "Download Android App" : "Download latest version"}}
                    </a>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";
import ContentHelpers from "../../../helpers/ContentHelpers.js";
import UserIdentity from "../../../models/UserIdentity.js";
import AboutInfo from "./AboutInfo";
import { Preferences } from '@capacitor/preferences';

export default {
  name: "HoMe",
  components: {
    AboutInfo
  },
  data() {
    return {
        username: "",
        password: "",
        interval: null,
        rmCheck: null,
        usernameInput: null,
        triedLogging: false,
        content: null
    }
  },
  beforeMount() {
    this.$store.state.loading = true;
    
    if(!this.$store.state.isWeb) {
        if (this.$store.state.tokenModel) {
            this.openPage("Finance");
        }
    }
  },
  async mounted() {
    if(!this.$store.state.isWeb) {
        await Preferences.get({ key: 'login' })
            .then((login) => {
                this.username = login.value;
            });
        
        await Preferences.get({ key: 'pass' })
            .then((pass) => {
                this.password = pass.value;
            });

        if (!this.$store.state.tokenModel) {
            await this.login();
        }
    }

    this.$store.state.apkDownloadUrl = await CommunicationHelpers.apiDataCall("/api/v1/content", this.$store.state, 'GET', { 'placement': "ApkDownloadUrl" }, false);
    this.$store.state.shortHomePageUpdate = ContentHelpers.getContentHtml(JSON.parse(await CommunicationHelpers.apiDataCall("/api/v1/content", this.$store.state, 'GET', { 'placement': "ShortHomePageUpdate" }, false)));

    this.$store.state.loading = false;
  },

  computed() {
    this.rmCheck = document.getElementById("RememberMe");
    this.usernameInput = document.getElementById("Username");

    if(this.rmCheck && this.usernameInput) {
        if (localStorage.checkbox && localStorage.checkbox !== "") {
            this.rmCheck.setAttribute("checked", "checked");
            this.usernameInput.value = localStorage.login;
            this.username = localStorage.login;
        } else {
            this.rmCheck.removeAttribute("checked");
            this.usernameInput.value = "";
        }
    }
  },

  methods: {
    openPage(name) {
        scroll(0,0);
        this.$router.push(name);
    },
    focus(id) {
        document.getElementById(id).focus();
    },
    async login(event) {
        if(event){
            this.triedLogging = true;
        }

        if(!this.username || !this.username.trim() || !this.password || !this.password.trim()) {
            if (event) {
                this.password = "";
                event.preventDefault();
            }
        } else {
            this.triedLogging = false;

            this.$store.state.loading = true;

            this.rmCheck = document.getElementById("RememberMe");
            this.usernameInput = document.getElementById("Username");

            if (!this.$store.state.isWeb) {
                if (this.username.trim() !== "" && this.password.trim() !== "") {
                    await Preferences.set({
                        key: 'login',
                        value: this.username.trim()
                    });

                    await Preferences.set({
                        key: 'pass',
                        value: this.password.trim()
                    });
                }
            } else {
                if (this.rmCheck.checked && this.username.trim() !== "") {
                    localStorage.login = this.usernameInput.value;
                    localStorage.checkbox = this.rmCheck.value;
                } else {
                    localStorage.login = "";
                    localStorage.checkbox = "";
                }
            }

            this.$store.state.userIdentity = new UserIdentity();
            this.$store.state.userIdentity.user.username = this.username.trim();
            this.$store.state.tokenModel = CommunicationHelpers.encodeStringToUtf8(this.username.trim() + ":" + this.password.trim());
            
            this.$store.state.tokenModel = await CommunicationHelpers.apiDataCall("/api/v1/auth/login", this.$store.state, 'POST',
            {
                'username': this.$store.state.userIdentity.user.username,
                'encodedPassword': this.$store.state.tokenModel
            }, true);
            localStorage.setItem("tokenModel", JSON.stringify(this.$store.state.tokenModel));
            localStorage.setItem("tokenSetTime", Date.now());
 
            if(this.$store.state.tokenModel && !CommunicationHelpers.isEmpty(this.$store.state.tokenModel)) {

                localStorage.login = this.username.trim();
                localStorage.tokenModel = JSON.stringify(this.$store.state.tokenModel);

                this.$store.state.userIdentity.user.isAdmin = JSON.parse(atob(this.$store.state.tokenModel.accessToken.split('.')[1]).toString()).role == "Admin"
                
                if (!this.$store.state.isWeb) {
                    this.openPage("Finance");
                }
            } else {
                this.triedLogging = true;

                this.$store.state.tokenModel = null;
            }
            this.password = "";

            this.$store.state.loading = false;
        }
    }
  }
};
</script>