export default class MvvMAccount {
    constructor(dataRow) {
        if(dataRow) {
            this.id = dataRow.id;
            this.name = dataRow.name;
            this.isDefault = dataRow.isDefault;
            this.amount = dataRow.amount;
        } else {
            this.id = 0;
            this.name = null;
            this.isDefault = false;
            this.amount = 0.0;
        }
    }
}

export function GetMvvMAccount(dataRow) {
    return new MvvMAccount(dataRow);
  }