<template>
  <div class="navbar navbar-inverse navbar-fixed-top heade">
    <div class="container">
      <div class="navbar-header" id="LogoControl" :class="$store.state.tokenModel ? 'logo-control-container' : ''">
        <button id="Toggle" type="button" class="navbar-toggle" data-toggle="collapse" data-target=".navbar-collapse" v-if="$store.state.tokenModel" onclick="this.classList.toggle('change');">
          <span class="icon-bar bar1"></span>
          <span class="icon-bar bar2"></span>
          <span class="icon-bar bar3"></span>
        </button>
        <a class="navbar-brand link" :class="$store.state.tokenModel ? 'logo-control-a' : ''" id="Logo" @click="openPage('/')" onclick="if(innerWidth <= 800 && $('#Toggle').hasClass('change')) document.getElementById('Toggle').click()" style="font-size: px"><img :src="getImage()" height="20" style="display:inline-block; padding-right:8px"/>Accounting</a>
      </div>
      <div class="navbar-collapse collapse">
        <ul class="nav navbar-nav">
          <li><a id="ManageData" class="link" @click="openPage('Finance')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.tokenModel && !$store.state.userIdentity.user.isAdmin">Finance</a></li>
          <li><a id="ManagePeriodicTransactions" class="link" @click="openPage('PeriodicTransactions')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.tokenModel && !$store.state.userIdentity.user.isAdmin">Periodic Transactions</a></li>
          <li><a id="ManageAccounts" class="link" @click="openPage('Accounts')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.tokenModel && !$store.state.userIdentity.user.isAdmin">Accounts</a></li>
          <li><a id="ManageNames" class="link" @click="openPage('Categories')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.tokenModel && !$store.state.userIdentity.user.isAdmin">Categories</a></li>
          <li><a id="Overview" class="link" @click="openPage('Overview')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.tokenModel && !$store.state.userIdentity.user.isAdmin">Overview</a></li>
          <li><a id="Administration" class="link" @click="openPage('Administration')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" v-if="$store.state.tokenModel && $store.state.userIdentity.user.isAdmin">Administration</a></li>
        </ul>
        <ul class="nav navbar-nav navbar-right">
          <li class="nav-item dropdown">
            <a class="nav-link dropdown-toggle" id="navbardrop" data-toggle="dropdown" v-if="$store.state.tokenModel">
              <div v-if="$store.state.userIdentity.user">
                {{$store.state.userIdentity.user.username}}
              </div>
            </a>
            <div class="dropdown-menu">
              <a id="UserProfile" @click="openPage('Profile')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" class="dropdown-item">Profile</a>
              <a v-if="!$store.state.isWeb && !$store.state.userIdentity.user.isAdmin" id="About" class="dropdown-item" @click="openPage('About')" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()">About</a>
              <a id="Logout" @click="logout()" onclick="if(innerWidth <= 800) document.getElementById('Toggle').click()" class="dropdown-item">Logout</a>
            </div>
          </li>
        </ul>
      </div>
    </div>
  </div>
</template>


<script>
import CommunicationHelpers from "../../helpers/CommunicationHelpers.js";
import { Preferences } from '@capacitor/preferences';
import jQuery from "jquery";
const $ = jQuery;
window.$ = $;

export default {
  name: "NaviGation",
  components: {
  },
  async mounted() {
    $(document).on('click', function () {
      $('.collapse').removeClass('show');
    });

    if (localStorage.tokenModel && localStorage.login) {
        this.$store.state.loading = true;

        this.$store.state.tokenModel = JSON.parse(localStorage.tokenModel);
        this.$store.state.userIdentity.user.username = localStorage.login;

        this.$store.state.tokenModel = await CommunicationHelpers.apiDataCall("/api/v1/auth/refresh", this.$store.state, 'PUT', this.$store.state.tokenModel, true);
        localStorage.setItem("tokenModel", JSON.stringify(this.$store.state.tokenModel));
        localStorage.setItem("tokenSetTime", Date.now());

        this.$store.state.userIdentity.user.isAdmin = JSON.parse(atob(this.$store.state.tokenModel.accessToken.split('.')[1]).toString()).role == "Admin"

        if (this.$store.state.userIdentity.user) {
            this.interval = await setInterval(this.renewToken, 10000);
        }

        this.$store.state.loading = false;
    }
  },
  methods: {
    openPage(name) {
      this.$router.push(name);
    },
    async renewToken() {
        let tokenSetTime = localStorage.getItem("tokenSetTime");
        const timeout = this.$store.state.tokenLifeSpan;

        if (this.$store.state.tokenModel && tokenSetTime && (Date.now() - tokenSetTime > (timeout - 60000)) && (Date.now() - tokenSetTime < (timeout - 50000))) {
            if (this.$store.state.isWeb){
                if (confirm('Your session will soon expire, do you wish to continue using "' + this.$router.currentRoute.value.name + ' - Accounting"?')) {
                    if (Date.now() - tokenSetTime > timeout) {
                        CommunicationHelpers.getAlerts({message: { errors: [ "Your session has already expired. Logging out..." ] }});
                        setTimeout(() => this.$store.commit('resetStore', this.$store.state), 3000);
                    } else {
                        this.$store.state.tokenModel = await CommunicationHelpers.apiDataCall("/api/v1/auth/refresh", this.$store.state, 'PUT', this.$store.state.tokenModel, true);
                        localStorage.setItem("tokenModel", JSON.stringify(this.$store.state.tokenModel));
                        localStorage.setItem("tokenSetTime", Date.now());
                    }
                } else {
                    await this.$store.commit('resetStore', this.$store.state);
                }
            } else {
                this.$store.state.tokenModel = await CommunicationHelpers.apiDataCall("/api/v1/auth/refresh", this.$store.state, 'PUT', this.$store.state.tokenModel, true);
                localStorage.setItem("tokenModel", JSON.stringify(this.$store.state.tokenModel));
                localStorage.setItem("tokenSetTime", Date.now());
            }
        }
    },
    async logout() {
      this.$store.state.loading = true;

      await CommunicationHelpers.apiDataCall("/api/v1/auth/revoke", this.$store.state, 'POST', null, false);

      await this.$store.commit('resetStore', this.$store.state);
      
      if(!this.$store.state.isWeb) {
        await Preferences.remove({
          key: 'pass'
        });
      }

      this.passwordInput = document.getElementById("Password");
      
      if(this.passwordInput) {
        this.passwordInput.value = "";
      }
      
      this.$store.state.loading = false;
    },

    getImage() {
      return "data:image/x-icon;base64," + 
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "" +
      "";
    }
  }
};
</script>