import MvvMTransaction from "./MvvMTransaction";

export default class MvvMPeriodicTransaction {
    constructor(dataRow) {
        if(dataRow) {
            this.id = dataRow.id;
            this.transaction = dataRow.transaction;
            this.name = dataRow.name;
            this.cronExpression = dataRow.cronExpression;
            this.startDate = dataRow.startDate;
            this.endDate = dataRow.endDate;
            this.isActive = dataRow.isActive;
        } else {
            this.id = 0;
            this.transaction = new MvvMTransaction();
            this.name = null;
            this.cronExpression = null;
            this.startDate = new Date();
            this.endDate = null;
            this.isActive = false;
        }
    }
}

export function GetMvvMPeriodicTransaction(dataRow) {
    return new MvvMPeriodicTransaction(dataRow);
}
