import { createRouter, createWebHashHistory } from "vue-router";
import Home from '../components/Layout/MainWindow/Home';
import Profile from '../components/Layout/MainWindow/Profile';
import Register from '../components/Layout/MainWindow/Register';
import ContactUs from '../components/Layout/MainWindow/ContactUs';
import About from '../components/Layout/MainWindow/About';
import Recover from '../components/Layout/MainWindow/Recover';
import Administration from '../components/Layout/MainWindow/Administration';
import Finance from '../components/Layout/MainWindow/Finance';
import PeriodicTransactions from '../components/Layout/MainWindow/PeriodicTransactions';
import Categories from '../components/Layout/MainWindow/Names';
import Accounts from '../components/Layout/MainWindow/Accounts';
import Notice from '../components/Layout/MainWindow/Notice';
import Overview from '../components/Layout/MainWindow/Overview.vue';

export const router = createRouter({
  history: createWebHashHistory(process.env.BASE_URL),
  routes: [
    {
      path: '/',
      name: 'Home',
      component: Home
    },
    {
      path: '/profile',
      name: 'Profile',
      component: Profile
    },
    {
      path: '/register',
      name: 'Sign Up',
      component: Register
    },
    {
      path: '/contactus',
      name: 'Contact Us',
      component: ContactUs
    },
    {
      path: '/about',
      name: 'About',
      component: About
    },
    {
      path: '/recover',
      name: 'Recover Password',
      component: Recover
    },
    {
      path: '/administration',
      name: 'Administration',
      component: Administration
    },
    {
      path: '/finance',
      name: 'Finance',
      component: Finance
    },
    {
      path: '/periodictransactions',
      name: 'Periodic Transactions',
      component: PeriodicTransactions
    },
    {
      path: '/accounts',
      name: 'Accounts',
      component: Accounts
    },
    {
      path: '/categories',
      name: 'Categories',
      component: Categories
    },
    {
      path: '/notice',
      name: 'Notice',
      component: Notice
    },
    {
      path: '/overview',
      name: 'Overview',
      component: Overview
    }
  ]
});
