export default class MvvMCategory {
    constructor(dataRow) {
        if(dataRow) {
            this.id = dataRow.id;
            this.name = dataRow.name;
            this.parentId = dataRow.parentId;
            this.categories = dataRow.categories;
        } else {
            this.id = 0;
            this.name = null;
            this.parentId = null;
            this.categories = [];
        }
    }
}

export function GetMvvMCategory(dataRow) {
    return new MvvMCategory(dataRow);
}
