<template>
    <div class="container">
        <div class="row">
            <h2>{{this.$router.currentRoute.value.name}}</h2>
            <div class="col-xs-12 col-sm-4 col-md-3 name_pos_1">
                <div class="block-data block" style="min-height: 0px!important">
                    <h3>Tips</h3>
                    <hr>
                    <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
                        This is the place to recover your <b>lost password</b>.
                        <p />
                        You will only need your:
                        <ul style="padding-left: 20px; font-style:italic">
                            <li>username</li>
                            <li>active recovery email account</li>
                        </ul>
                        In case you can't remember any of these details feel free to
                        <a @click="openPage('ContactUs')" class="btn" style="text-decoration:none; padding:0;">contact us</a>.
                    </div>
                </div>
            </div>
            <div class="col-xs-12 col-sm-8 col-md-9">
                <div class="block block-scaf block-data">
                    <label for="Username">Username:</label>
                    <br />
                    <input id="Username" class="form-control form-text-valid" maxlength="100" v-on:keyup.enter="focus('RecoveryEmail')" v-model="username" />
                    <span class="tdspaced" style="color: red;" v-if="triedRecovering && !username.trim()">*</span>
                    <br />
                    <br />
                    <label for="RecoveryEmail">Email:</label>
                    <br />
                    <input id="RecoveryEmail" class="form-control form-text-valid" maxlength="100" v-on:keyup.enter="recover($event)" v-model="email" />
                    <span class="tdspaced" style="color: red;" v-if="triedRecovering && !email.trim()">*</span>
                    <span style="color: red; display: block; padding: 20px 0px" v-if="!validateEmail(email) && email.trim()">Invalid format</span>
                    <button id="RecoverButton" class="btn btn-primary profileBtn" Width="60%" @click="recover($event)">Send New Password</button>
                    <button id="CancelButton" class="btn btn-danger profileBtn" Width="60%" @click="cancel()">Cancel</button>
                </div>
            </div>
            <div class="col-xs-12 col-sm-4 col-md-3 name_pos_2">
                <div class="block" style="min-height: 0px!important">
                    <h3>Tips</h3>
                    <hr>
                    <div style="text-align: justify; padding-top: 0px!important; padding: 5%;">
                        This is the place to recover your <b>lost password</b>.
                        <p />
                        You will only need your:
                        <ul style="padding-left: 20px; font-style:italic">
                            <li>username</li>
                            <li>active recovery email account</li>
                        </ul>
                        In case you can't remember any of these details feel free to
                        <a @click="openPage('ContactUs')" class="btn" style="text-decoration:none; padding:0;">contact us</a>.
                    </div>
                </div>
            </div>
        </div>
    </div>
</template>

<script>
import CommunicationHelpers from "../../../helpers/CommunicationHelpers.js";
import UserIdentity from "../../../models/UserIdentity.js";

export default {
  name: "ReCover",
  data() {
    return {
        username: "",
        email: "",
        triedRecovering: false
    }
  },

  methods: {
      openPage(name) {
        this.$router.push(name);
      },
      validateEmail(value) {
        return CommunicationHelpers.validateEmail(value);
      },
      focus(id) {
        document.getElementById(id).focus();
      },
      async recover(event) {
        this.triedRecovering = true;

        if(!this.username.trim() || !this.email.trim()) {
            event.preventDefault();
        } else {
            this.$store.state.loading = true;

            this.triedRecovering = false;

            this.$store.state.userIdentity = new UserIdentity();
            this.$store.state.userIdentity.user.username = this.username.trim();
            this.$store.state.userIdentity.user.recoveryEmail = this.email.trim();
                
            if(CommunicationHelpers.displaySuccessResponse(await CommunicationHelpers.apiDataCall("/api/v1/auth/SendNewPassword", this.$store.state, 'POST',
                    { 'username': this.$store.state.userIdentity.user.username, 'recoveryEmail': this.$store.state.userIdentity.user.recoveryEmail }, false))) {
                this.username = "";
                this.email = "";
            }

            this.$store.state.loading = false;
        }
      },
      cancel() {
          if(confirm("Are you sure?")) {
            this.$router.push('/');
          }
      }
  }
};
</script>