export default class MvvMTransaction {
    constructor(dataRow) {
        if(dataRow) {
            this.id = dataRow.id;
            this.type = dataRow.type;
            this.category = dataRow.category;
            this.account = dataRow.account;
            this.sourceAccount = dataRow.sourceAccount;
            this.amount = dataRow.amount;
            this.comments = dataRow.comments;
            this.date = dataRow.date;
            this.timeStamp = dataRow.timeStamp;
        } else {
            this.id = 0;
            this.type = null;
            this.category = null;
            this.account = null;
            this.sourceAccount = null;
            this.amount = 0;
            this.comments = null;
            this.date = new Date();
            this.timeStamp = new Date();
        }
    }
}

export function GetMvvMTransaction(dataRow) {
    return new MvvMTransaction(dataRow);
}
